    d.stage = GUIDEXOS_NATIVEAOT_ALLOC_STAGE_F33_NEXT_GENUINE_ROOT_PROVIDER_SAFE_STOP;
    d.rootBoundaryFunction = d.c011ec15StopAddress;
    validateAllocationContextFixupObjects(true);
