    uintptr_t markedBytes;
    uintptr_t markedBytesAtDecision;
    uint32_t markedObjectsAtFirstDecision;
    uintptr_t markedBytesAtFirstDecision;
    uintptr_t firstMarkedObject;
    uintptr_t lastMarkedObject;
